CREATE TABLE advanced_routing_global(id INTEGER PRIMARY KEY CHECK(id=1),enabled INTEGER NOT NULL DEFAULT 1,engine TEXT NOT NULL DEFAULT 'policy table -> route_reload',apply_state TEXT NOT NULL DEFAULT 'draft',last_apply_at INTEGER NOT NULL DEFAULT 0,default_table TEXT NOT NULL DEFAULT 'main',object_revision INTEGER NOT NULL DEFAULT 0,health_aware INTEGER NOT NULL DEFAULT 1,log_policy_hits INTEGER NOT NULL DEFAULT 1,updated_at INTEGER NOT NULL DEFAULT 0);
CREATE TABLE aegis_settings ( id INTEGER PRIMARY KEY CHECK(id=1), enabled INTEGER NOT NULL DEFAULT 0, mode TEXT NOT NULL DEFAULT 'off', source_level TEXT NOT NULL DEFAULT 'open', suricata_version TEXT NOT NULL DEFAULT 'auto', default_action TEXT NOT NULL DEFAULT 'alert', logging_enabled INTEGER NOT NULL DEFAULT 1, updated_at INTEGER NOT NULL DEFAULT 0);
CREATE TABLE ai_conversation ( id TEXT PRIMARY KEY, title TEXT NOT NULL DEFAULT '', model TEXT NOT NULL DEFAULT '', reasoning_effort TEXT NOT NULL DEFAULT 'auto', message_count INTEGER NOT NULL DEFAULT 0, prompt_tokens INTEGER NOT NULL DEFAULT 0, completion_tokens INTEGER NOT NULL DEFAULT 0, total_tokens INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE ai_message ( id INTEGER PRIMARY KEY AUTOINCREMENT, conversation_id TEXT NOT NULL, message_id TEXT NOT NULL DEFAULT '', role TEXT NOT NULL, content TEXT NOT NULL DEFAULT '', attachments_json TEXT NOT NULL DEFAULT '[]', created_at INTEGER NOT NULL, FOREIGN KEY(conversation_id) REFERENCES ai_conversation(id) ON DELETE CASCADE);
CREATE TABLE client_control_rules ( id TEXT PRIMARY KEY, mac TEXT NOT NULL, name TEXT NOT NULL DEFAULT '', enabled INTEGER NOT NULL DEFAULT 1, control_type TEXT NOT NULL DEFAULT 'IP限速', schedule_mode TEXT NOT NULL DEFAULT 'week', days_json TEXT NOT NULL DEFAULT '[]', days_text TEXT NOT NULL DEFAULT '', start_time TEXT NOT NULL DEFAULT '00:00', end_time TEXT NOT NULL DEFAULT '23:59', limit_mode TEXT NOT NULL DEFAULT '独立限速', up_limit INTEGER NOT NULL DEFAULT 0, up_unit TEXT NOT NULL DEFAULT 'KB/s', down_limit INTEGER NOT NULL DEFAULT 0, down_unit TEXT NOT NULL DEFAULT 'KB/s', line TEXT NOT NULL DEFAULT '', protocol TEXT NOT NULL DEFAULT '任意', note TEXT NOT NULL DEFAULT '', runtime_apply INTEGER NOT NULL DEFAULT 0, apply_state TEXT NOT NULL DEFAULT 'draft', apply_reason TEXT NOT NULL DEFAULT '', created_at INTEGER NOT NULL DEFAULT 0, updated_at INTEGER NOT NULL DEFAULT 0, last_runtime_enabled INTEGER NOT NULL DEFAULT -1, last_runtime_apply_at INTEGER NOT NULL DEFAULT 0, last_runtime_reason TEXT NOT NULL DEFAULT '');
CREATE TABLE cross_l3_service(id TEXT PRIMARY KEY,enabled INTEGER NOT NULL DEFAULT 1,name TEXT NOT NULL,service_type TEXT NOT NULL DEFAULT 'snmp',server_ip TEXT NOT NULL DEFAULT '',scope TEXT NOT NULL DEFAULT '',listen_port TEXT NOT NULL DEFAULT '161',version TEXT NOT NULL DEFAULT 'V2',access_rate TEXT NOT NULL DEFAULT '',remark TEXT NOT NULL DEFAULT '',updated_at INTEGER NOT NULL DEFAULT 0);
CREATE TABLE dhcp_lease_cache ( mac TEXT PRIMARY KEY, scope_id TEXT, hostname TEXT DEFAULT '', ip TEXT NOT NULL, expires_at INTEGER DEFAULT 0, online INTEGER DEFAULT 0, updated_at INTEGER DEFAULT 0);
CREATE TABLE dhcp_option ( id TEXT PRIMARY KEY, scope_id TEXT NOT NULL, code TEXT NOT NULL, value TEXT NOT NULL, sort_order INTEGER DEFAULT 0);
CREATE TABLE dhcp_reservation ( id TEXT PRIMARY KEY, scope_id TEXT NOT NULL, name TEXT DEFAULT '', mac TEXT NOT NULL, ip TEXT NOT NULL, remark TEXT DEFAULT '', enabled INTEGER DEFAULT 1, UNIQUE(scope_id, mac), UNIQUE(scope_id, ip));
CREATE TABLE dhcp_scope ( id TEXT PRIMARY KEY, lan_id TEXT NOT NULL, enabled INTEGER DEFAULT 1, tagname TEXT DEFAULT '', pool_start TEXT DEFAULT '', pool_end TEXT DEFAULT '', exclude_pool TEXT DEFAULT '', gateway TEXT DEFAULT '', netmask TEXT DEFAULT '', dns1 TEXT DEFAULT '', dns2 TEXT DEFAULT '', lease_minutes INTEGER DEFAULT 120, domain TEXT DEFAULT '', updated_at INTEGER DEFAULT 0, UNIQUE(lan_id));
CREATE TABLE dns_listen_interface ( service_id INTEGER NOT NULL DEFAULT 1, lan_id TEXT NOT NULL, PRIMARY KEY(service_id, lan_id));
CREATE TABLE dns_rule ( id TEXT PRIMARY KEY, domain TEXT NOT NULL, type TEXT NOT NULL, target TEXT DEFAULT '', remark TEXT DEFAULT '', enabled INTEGER DEFAULT 1, sort_order INTEGER DEFAULT 0, UNIQUE(domain, type));
CREATE TABLE dns_runtime_stat ( key TEXT PRIMARY KEY, value TEXT DEFAULT '', updated_at INTEGER DEFAULT 0);
CREATE TABLE dns_service ( id INTEGER PRIMARY KEY CHECK (id = 1), enabled INTEGER DEFAULT 1, mode TEXT DEFAULT 'proxy', listen_port INTEGER DEFAULT 53, cache_enabled INTEGER DEFAULT 1, cache_size INTEGER DEFAULT 4096, local_domain TEXT DEFAULT 'lan', rebind_protection INTEGER DEFAULT 1, hijack_protection INTEGER DEFAULT 1, edns_client_subnet INTEGER DEFAULT 0, ipv6_dns INTEGER DEFAULT 1, updated_at INTEGER DEFAULT 0);
CREATE TABLE dns_upstream ( id TEXT PRIMARY KEY, name TEXT DEFAULT '', address TEXT NOT NULL, port INTEGER DEFAULT 53, protocol TEXT DEFAULT 'udp', group_name TEXT DEFAULT '默认', enabled INTEGER DEFAULT 1, sort_order INTEGER DEFAULT 0);
CREATE TABLE flowd_app_rules ( id TEXT PRIMARY KEY, name TEXT NOT NULL DEFAULT '', enabled INTEGER NOT NULL DEFAULT 1, priority INTEGER NOT NULL DEFAULT 1000, action TEXT NOT NULL DEFAULT 'mark', src_object TEXT NOT NULL DEFAULT '', app_object TEXT NOT NULL DEFAULT '', time_object TEXT NOT NULL DEFAULT '', route_group TEXT NOT NULL DEFAULT '', qos_class TEXT NOT NULL DEFAULT '', mark TEXT NOT NULL DEFAULT '', log_event INTEGER NOT NULL DEFAULT 1, remark TEXT NOT NULL DEFAULT '', created_at INTEGER NOT NULL DEFAULT 0, updated_at INTEGER NOT NULL DEFAULT 0);
CREATE TABLE flowd_apply_jobs ( id TEXT PRIMARY KEY, kind TEXT NOT NULL DEFAULT 'compile', requested_by TEXT NOT NULL DEFAULT '', state TEXT NOT NULL DEFAULT 'compiled', dry_run INTEGER NOT NULL DEFAULT 1, plan_path TEXT NOT NULL DEFAULT '', plan_json TEXT NOT NULL DEFAULT '{}', error TEXT NOT NULL DEFAULT '', created_at INTEGER NOT NULL DEFAULT 0, updated_at INTEGER NOT NULL DEFAULT 0, completed_at INTEGER NOT NULL DEFAULT 0);
CREATE TABLE flowd_conn_limit_rules ( id TEXT PRIMARY KEY, name TEXT NOT NULL DEFAULT '', enabled INTEGER NOT NULL DEFAULT 1, priority INTEGER NOT NULL DEFAULT 1000, scope TEXT NOT NULL DEFAULT 'per_host', action TEXT NOT NULL DEFAULT 'reject_new', src_object TEXT NOT NULL DEFAULT '', dst_object TEXT NOT NULL DEFAULT '', service_object TEXT NOT NULL DEFAULT '', time_object TEXT NOT NULL DEFAULT '', proto TEXT NOT NULL DEFAULT 'any', conn_limit INTEGER NOT NULL DEFAULT 0, burst INTEGER NOT NULL DEFAULT 0, log_event INTEGER NOT NULL DEFAULT 1, remark TEXT NOT NULL DEFAULT '', created_at INTEGER NOT NULL DEFAULT 0, updated_at INTEGER NOT NULL DEFAULT 0);
CREATE TABLE flowd_country_policies ( id TEXT PRIMARY KEY, name TEXT NOT NULL DEFAULT '', enabled INTEGER NOT NULL DEFAULT 1, priority INTEGER NOT NULL DEFAULT 1000, direction TEXT NOT NULL DEFAULT 'dst', countries_json TEXT NOT NULL DEFAULT '[]', action TEXT NOT NULL DEFAULT 'route', target TEXT NOT NULL DEFAULT '', family TEXT NOT NULL DEFAULT 'both', remark TEXT NOT NULL DEFAULT '', created_at INTEGER NOT NULL DEFAULT 0, updated_at INTEGER NOT NULL DEFAULT 0);
CREATE TABLE flowd_custom_protocols ( id TEXT PRIMARY KEY, name TEXT NOT NULL DEFAULT '', enabled INTEGER NOT NULL DEFAULT 1, priority INTEGER NOT NULL DEFAULT 1000, kind TEXT NOT NULL DEFAULT 'l4', proto TEXT NOT NULL DEFAULT 'tcp', src_port TEXT NOT NULL DEFAULT '', dst_port TEXT NOT NULL DEFAULT '', match_json TEXT NOT NULL DEFAULT '{}', tags_json TEXT NOT NULL DEFAULT '[]', remark TEXT NOT NULL DEFAULT '', created_at INTEGER NOT NULL DEFAULT 0, updated_at INTEGER NOT NULL DEFAULT 0);
CREATE TABLE flowd_domain_rules ( id TEXT PRIMARY KEY, name TEXT NOT NULL DEFAULT '', enabled INTEGER NOT NULL DEFAULT 1, priority INTEGER NOT NULL DEFAULT 1000, action TEXT NOT NULL DEFAULT 'route', domain_object TEXT NOT NULL DEFAULT '', src_object TEXT NOT NULL DEFAULT '', time_object TEXT NOT NULL DEFAULT '', route_group TEXT NOT NULL DEFAULT '', fallback TEXT NOT NULL DEFAULT 'main', family TEXT NOT NULL DEFAULT 'both', mark TEXT NOT NULL DEFAULT '', log_event INTEGER NOT NULL DEFAULT 1, remark TEXT NOT NULL DEFAULT '', created_at INTEGER NOT NULL DEFAULT 0, updated_at INTEGER NOT NULL DEFAULT 0);
CREATE TABLE flowd_geoip_sources ( id TEXT PRIMARY KEY, name TEXT NOT NULL DEFAULT '', type TEXT NOT NULL DEFAULT 'maxmind-mmdb', path TEXT NOT NULL DEFAULT '', edition TEXT NOT NULL DEFAULT '', enabled INTEGER NOT NULL DEFAULT 1, auto_update INTEGER NOT NULL DEFAULT 0, license_ref TEXT NOT NULL DEFAULT '', meta_json TEXT NOT NULL DEFAULT '{}', created_at INTEGER NOT NULL DEFAULT 0, updated_at INTEGER NOT NULL DEFAULT 0, last_import_at INTEGER NOT NULL DEFAULT 0, last_import_status TEXT NOT NULL DEFAULT 'never', last_error TEXT NOT NULL DEFAULT '');
CREATE TABLE flowd_objects ( id TEXT PRIMARY KEY, type TEXT NOT NULL DEFAULT 'ipv4', name TEXT NOT NULL DEFAULT '', enabled INTEGER NOT NULL DEFAULT 1, value_json TEXT NOT NULL DEFAULT '[]', remark TEXT NOT NULL DEFAULT '', created_at INTEGER NOT NULL DEFAULT 0, updated_at INTEGER NOT NULL DEFAULT 0);
CREATE TABLE flowd_qos_classes ( id TEXT PRIMARY KEY, name TEXT NOT NULL DEFAULT '', enabled INTEGER NOT NULL DEFAULT 1, priority INTEGER NOT NULL DEFAULT 100, guarantee_pct INTEGER NOT NULL DEFAULT 0, ceiling_pct INTEGER NOT NULL DEFAULT 100, latency_ms INTEGER NOT NULL DEFAULT 0, dscp TEXT NOT NULL DEFAULT '', color TEXT NOT NULL DEFAULT '', remark TEXT NOT NULL DEFAULT '', created_at INTEGER NOT NULL DEFAULT 0, updated_at INTEGER NOT NULL DEFAULT 0);
CREATE TABLE flowd_qos_rules ( id TEXT PRIMARY KEY, name TEXT NOT NULL DEFAULT '', enabled INTEGER NOT NULL DEFAULT 1, priority INTEGER NOT NULL DEFAULT 1000, class_id TEXT NOT NULL DEFAULT '', direction TEXT NOT NULL DEFAULT 'both', family TEXT NOT NULL DEFAULT 'both', interface TEXT NOT NULL DEFAULT '', src_object TEXT NOT NULL DEFAULT '', dst_object TEXT NOT NULL DEFAULT '', app_object TEXT NOT NULL DEFAULT '', service_object TEXT NOT NULL DEFAULT '', time_object TEXT NOT NULL DEFAULT '', rate_kbps INTEGER NOT NULL DEFAULT 0, ceil_kbps INTEGER NOT NULL DEFAULT 0, per_host INTEGER NOT NULL DEFAULT 0, match_json TEXT NOT NULL DEFAULT '{}', remark TEXT NOT NULL DEFAULT '', created_at INTEGER NOT NULL DEFAULT 0, updated_at INTEGER NOT NULL DEFAULT 0);
CREATE TABLE flowd_qos_settings ( id INTEGER PRIMARY KEY CHECK(id=1), enabled INTEGER NOT NULL DEFAULT 0, scheduler TEXT NOT NULL DEFAULT 'htb', default_class TEXT NOT NULL DEFAULT 'normal', unknown_class TEXT NOT NULL DEFAULT 'normal', headroom_pct INTEGER NOT NULL DEFAULT 95, diffserv INTEGER NOT NULL DEFAULT 1, ack_filter INTEGER NOT NULL DEFAULT 0, fairness TEXT NOT NULL DEFAULT 'per_host', remark TEXT NOT NULL DEFAULT '', updated_at INTEGER NOT NULL DEFAULT 0);
CREATE TABLE flowd_quota_rules ( id TEXT PRIMARY KEY, name TEXT NOT NULL DEFAULT '', enabled INTEGER NOT NULL DEFAULT 1, priority INTEGER NOT NULL DEFAULT 1000, scope TEXT NOT NULL DEFAULT 'daily', action TEXT NOT NULL DEFAULT 'throttle', target_object TEXT NOT NULL DEFAULT '', limit_bytes INTEGER NOT NULL DEFAULT 0, reset_hour INTEGER NOT NULL DEFAULT 0, timezone TEXT NOT NULL DEFAULT 'local', throttle_class TEXT NOT NULL DEFAULT '', notify INTEGER NOT NULL DEFAULT 1, log_event INTEGER NOT NULL DEFAULT 1, remark TEXT NOT NULL DEFAULT '', created_at INTEGER NOT NULL DEFAULT 0, updated_at INTEGER NOT NULL DEFAULT 0);
CREATE TABLE flowd_route_group_members ( id TEXT PRIMARY KEY, group_id TEXT NOT NULL, target TEXT NOT NULL DEFAULT '', weight INTEGER NOT NULL DEFAULT 100, role TEXT NOT NULL DEFAULT 'active', priority INTEGER NOT NULL DEFAULT 100, meta_json TEXT NOT NULL DEFAULT '{}', sort_order INTEGER NOT NULL DEFAULT 0, FOREIGN KEY(group_id) REFERENCES flowd_route_groups(id) ON DELETE CASCADE);
CREATE TABLE flowd_route_groups ( id TEXT PRIMARY KEY, name TEXT NOT NULL DEFAULT '', enabled INTEGER NOT NULL DEFAULT 1, mode TEXT NOT NULL DEFAULT 'weighted', hash TEXT NOT NULL DEFAULT 'src_ip,dst_ip,dst_port', health_check INTEGER NOT NULL DEFAULT 1, failback INTEGER NOT NULL DEFAULT 1, remark TEXT NOT NULL DEFAULT '', created_at INTEGER NOT NULL DEFAULT 0, updated_at INTEGER NOT NULL DEFAULT 0);
CREATE TABLE flowd_settings ( id INTEGER PRIMARY KEY CHECK(id=1), enabled INTEGER NOT NULL DEFAULT 1, geoip_dir TEXT NOT NULL DEFAULT '/etc/dreamingwrt/geoip', runtime_dir TEXT NOT NULL DEFAULT '/etc/dreamingwrt/geoip/runtime', apply_mode TEXT NOT NULL DEFAULT 'plan-only', updated_at INTEGER NOT NULL DEFAULT 0);
CREATE TABLE flowd_smart_qos_categories ( id TEXT PRIMARY KEY, name TEXT NOT NULL DEFAULT '', enabled INTEGER NOT NULL DEFAULT 1, category TEXT NOT NULL UNIQUE, priority INTEGER NOT NULL DEFAULT 500, qos_class TEXT NOT NULL DEFAULT '', latency_target_ms INTEGER NOT NULL DEFAULT 0, remark TEXT NOT NULL DEFAULT '', created_at INTEGER NOT NULL DEFAULT 0, updated_at INTEGER NOT NULL DEFAULT 0);
CREATE TABLE flowd_split_rules ( id TEXT PRIMARY KEY, name TEXT NOT NULL DEFAULT '', enabled INTEGER NOT NULL DEFAULT 1, priority INTEGER NOT NULL DEFAULT 1000, action TEXT NOT NULL DEFAULT 'route', target_group TEXT NOT NULL DEFAULT '', fallback TEXT NOT NULL DEFAULT 'main', family TEXT NOT NULL DEFAULT 'both', src_object TEXT NOT NULL DEFAULT '', dst_object TEXT NOT NULL DEFAULT '', app_object TEXT NOT NULL DEFAULT '', service_object TEXT NOT NULL DEFAULT '', time_object TEXT NOT NULL DEFAULT '', proto TEXT NOT NULL DEFAULT 'any', src_port TEXT NOT NULL DEFAULT '', dst_port TEXT NOT NULL DEFAULT '', match_json TEXT NOT NULL DEFAULT '{}', remark TEXT NOT NULL DEFAULT '', created_at INTEGER NOT NULL DEFAULT 0, updated_at INTEGER NOT NULL DEFAULT 0);
CREATE TABLE flowd_wan_capacity ( id TEXT PRIMARY KEY, name TEXT NOT NULL DEFAULT '', enabled INTEGER NOT NULL DEFAULT 1, wan TEXT NOT NULL UNIQUE, down_kbps INTEGER NOT NULL DEFAULT 0, up_kbps INTEGER NOT NULL DEFAULT 0, headroom_pct INTEGER NOT NULL DEFAULT 95, scheduler TEXT NOT NULL DEFAULT 'cake', link_layer TEXT NOT NULL DEFAULT 'ethernet', overhead_bytes INTEGER NOT NULL DEFAULT 0, ingress INTEGER NOT NULL DEFAULT 1, egress INTEGER NOT NULL DEFAULT 1, source TEXT NOT NULL DEFAULT 'manual', remark TEXT NOT NULL DEFAULT '', created_at INTEGER NOT NULL DEFAULT 0, updated_at INTEGER NOT NULL DEFAULT 0);
CREATE TABLE flowd_wan_health ( id TEXT PRIMARY KEY, name TEXT NOT NULL DEFAULT '', enabled INTEGER NOT NULL DEFAULT 1, wan TEXT NOT NULL DEFAULT '', method TEXT NOT NULL DEFAULT 'icmp', targets_json TEXT NOT NULL DEFAULT '[]', interval_s INTEGER NOT NULL DEFAULT 5, timeout_ms INTEGER NOT NULL DEFAULT 1000, loss_threshold_pct INTEGER NOT NULL DEFAULT 50, latency_threshold_ms INTEGER NOT NULL DEFAULT 300, fail_count INTEGER NOT NULL DEFAULT 3, recover_count INTEGER NOT NULL DEFAULT 2, remark TEXT NOT NULL DEFAULT '', created_at INTEGER NOT NULL DEFAULT 0, updated_at INTEGER NOT NULL DEFAULT 0);
CREATE TABLE hybrid_line ( id TEXT PRIMARY KEY, parent_wan_id TEXT NOT NULL, name TEXT NOT NULL, comment TEXT DEFAULT '', mode TEXT NOT NULL, vlan_id TEXT DEFAULT '', mac TEXT DEFAULT '', proto TEXT NOT NULL, enabled INTEGER DEFAULT 1, default_route INTEGER DEFAULT 0, failover INTEGER DEFAULT 1, check_host TEXT DEFAULT 'www.baidu.com', ip TEXT DEFAULT '', prefix INTEGER DEFAULT 24, gateway TEXT DEFAULT '', username TEXT DEFAULT '', password_ref TEXT DEFAULT '', pppoe_ac TEXT DEFAULT '', pppoe_ac_mac TEXT DEFAULT '', pppoe_service TEXT DEFAULT '', mtu INTEGER DEFAULT 1480, mru INTEGER DEFAULT 1480, upload_mbps INTEGER DEFAULT 0, download_mbps INTEGER DEFAULT 0, UNIQUE(parent_wan_id, name));
CREATE TABLE insights_map_local_locations ( wan_id TEXT PRIMARY KEY, public_ip TEXT NOT NULL DEFAULT '', enabled INTEGER NOT NULL DEFAULT 1, country_code TEXT NOT NULL DEFAULT '', country_name TEXT NOT NULL DEFAULT '', region_name TEXT NOT NULL DEFAULT '', city_name TEXT NOT NULL DEFAULT '', lat REAL NOT NULL, lon REAL NOT NULL, accuracy_radius INTEGER NOT NULL DEFAULT 0, updated_at INTEGER NOT NULL DEFAULT 0);
CREATE TABLE lan ( id TEXT PRIMARY KEY, name TEXT NOT NULL, note TEXT DEFAULT '', ifname TEXT NOT NULL, device TEXT NOT NULL, mode TEXT NOT NULL DEFAULT 'bridge', parent_lan_id TEXT DEFAULT '', vlan_id TEXT DEFAULT '', mac_clone TEXT DEFAULT '', speed TEXT DEFAULT '0', duplex TEXT DEFAULT '0', lan_visit INTEGER DEFAULT 1, enabled INTEGER DEFAULT 1, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE lan_address ( id TEXT PRIMARY KEY, lan_id TEXT NOT NULL, ip TEXT NOT NULL, prefix INTEGER NOT NULL, is_primary INTEGER DEFAULT 0, sort_order INTEGER NOT NULL, UNIQUE(lan_id, ip, prefix));
CREATE TABLE lan_dhcp ( lan_id TEXT PRIMARY KEY, enabled INTEGER DEFAULT 1, tagname TEXT DEFAULT '', pool_start TEXT DEFAULT '', pool_end TEXT DEFAULT '', exclude_pool_json TEXT DEFAULT '[]', gateway TEXT DEFAULT '', dns_json TEXT DEFAULT '[]', lease_minutes INTEGER DEFAULT 120);
CREATE TABLE lan_ipv6 ( lan_id TEXT PRIMARY KEY, enabled INTEGER DEFAULT 0, parent_wans_json TEXT DEFAULT '[]', mode TEXT DEFAULT 'dhcp', dhcpv6 INTEGER DEFAULT 1, static_addr TEXT DEFAULT '', use_dns6 INTEGER DEFAULT 0, dns6_json TEXT DEFAULT '[]', prefix_len TEXT DEFAULT 'auto', ra_flags TEXT DEFAULT '1', ra_static INTEGER DEFAULT 0, ra_mtu_set INTEGER DEFAULT 0, ra_mtu INTEGER DEFAULT 1480, lease_minutes INTEGER DEFAULT 120);
CREATE TABLE lan_port ( id TEXT PRIMARY KEY, lan_id TEXT NOT NULL, port TEXT NOT NULL, label TEXT DEFAULT '', sort_order INTEGER NOT NULL, UNIQUE(lan_id, port));
CREATE TABLE logd_collector_settings ( name TEXT PRIMARY KEY, enabled INTEGER NOT NULL DEFAULT 1, interval_s INTEGER NOT NULL DEFAULT 30, cooldown_s INTEGER NOT NULL DEFAULT 60, options_json TEXT NOT NULL DEFAULT '{}', updated_at INTEGER NOT NULL DEFAULT 0);
CREATE TABLE logd_collector_state ( name TEXT NOT NULL, key TEXT NOT NULL, value TEXT NOT NULL DEFAULT '', updated_at INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(name,key));
CREATE TABLE logd_settings ( id INTEGER PRIMARY KEY CHECK (id=1), retention_days INTEGER NOT NULL DEFAULT 30, kernel_retention_days INTEGER NOT NULL DEFAULT 7, max_size_mb INTEGER NOT NULL DEFAULT 128, max_events INTEGER NOT NULL DEFAULT 50000, auto_cleanup INTEGER NOT NULL DEFAULT 1, archive_compress INTEGER NOT NULL DEFAULT 1, updated_at INTEGER NOT NULL DEFAULT 0);
CREATE TABLE logd_syslog_config ( id INTEGER PRIMARY KEY CHECK (id=1), enabled INTEGER NOT NULL DEFAULT 0, server TEXT NOT NULL DEFAULT '', port INTEGER NOT NULL DEFAULT 514, protocol TEXT NOT NULL DEFAULT 'udp', facility TEXT NOT NULL DEFAULT 'local7', min_level TEXT NOT NULL DEFAULT 'notice', categories TEXT NOT NULL DEFAULT 'general,audit,security,wan,client,vpn', tls_ca_path TEXT NOT NULL DEFAULT '', tls_client_cert_path TEXT NOT NULL DEFAULT '', tls_client_key_path TEXT NOT NULL DEFAULT '', tls_verify_peer INTEGER NOT NULL DEFAULT 1, tls_verify_host INTEGER NOT NULL DEFAULT 1, tls_sni TEXT NOT NULL DEFAULT '', updated_at INTEGER NOT NULL DEFAULT 0);
CREATE TABLE logd_syslog_profiles ( profile_id TEXT PRIMARY KEY, name TEXT NOT NULL DEFAULT '', enabled INTEGER NOT NULL DEFAULT 0, server TEXT NOT NULL DEFAULT '', port INTEGER NOT NULL DEFAULT 514, protocol TEXT NOT NULL DEFAULT 'udp', facility TEXT NOT NULL DEFAULT 'local7', min_level TEXT NOT NULL DEFAULT 'notice', categories TEXT NOT NULL DEFAULT 'general,audit,security,wan,client,vpn', tls_ca_path TEXT NOT NULL DEFAULT '', tls_client_cert_path TEXT NOT NULL DEFAULT '', tls_client_key_path TEXT NOT NULL DEFAULT '', tls_verify_peer INTEGER NOT NULL DEFAULT 1, tls_verify_host INTEGER NOT NULL DEFAULT 1, tls_sni TEXT NOT NULL DEFAULT '', sort_order INTEGER NOT NULL DEFAULT 100, is_default INTEGER NOT NULL DEFAULT 0, updated_at INTEGER NOT NULL DEFAULT 0);
CREATE TABLE logd_syslog_queue ( id TEXT PRIMARY KEY, event_id TEXT NOT NULL DEFAULT '', ts INTEGER NOT NULL, protocol TEXT NOT NULL DEFAULT 'udp', server TEXT NOT NULL DEFAULT '', port INTEGER NOT NULL DEFAULT 514, profile_id TEXT NOT NULL DEFAULT 'default', profile_name TEXT NOT NULL DEFAULT 'Default Syslog', facility TEXT NOT NULL DEFAULT 'local7', severity TEXT NOT NULL DEFAULT 'info', category TEXT NOT NULL DEFAULT '', event TEXT NOT NULL DEFAULT '', payload TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'pending', attempts INTEGER NOT NULL DEFAULT 0, last_error TEXT NOT NULL DEFAULT '', created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, next_retry_at INTEGER NOT NULL DEFAULT 0, sent_at INTEGER NOT NULL DEFAULT 0);
CREATE TABLE logd_syslog_state ( id INTEGER PRIMARY KEY CHECK (id=1), last_test_at INTEGER NOT NULL DEFAULT 0, last_success_at INTEGER NOT NULL DEFAULT 0, last_error_at INTEGER NOT NULL DEFAULT 0, last_ok INTEGER NOT NULL DEFAULT 0, last_error TEXT NOT NULL DEFAULT '', last_message TEXT NOT NULL DEFAULT '', updated_at INTEGER NOT NULL DEFAULT 0);
CREATE TABLE network_global ( id INTEGER PRIMARY KEY CHECK (id = 1), default_posture TEXT DEFAULT 'allow', mdns_proxy TEXT DEFAULT 'auto', igmp_snooping INTEGER DEFAULT 0, stp_mode TEXT DEFAULT 'rstp', rogue_dhcp_detection INTEGER DEFAULT 0, jumbo_frames INTEGER DEFAULT 0, flow_control INTEGER DEFAULT 0, dot1x INTEGER DEFAULT 0, bridge_stp INTEGER DEFAULT 1, bridge_forward_delay INTEGER DEFAULT 2);
CREATE TABLE network_meta ( key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE notifyd_channels ( id TEXT PRIMARY KEY, name TEXT NOT NULL DEFAULT '', type TEXT NOT NULL DEFAULT 'noop', enabled INTEGER NOT NULL DEFAULT 1, options_json TEXT NOT NULL DEFAULT '{}', created_at INTEGER NOT NULL DEFAULT 0, updated_at INTEGER NOT NULL DEFAULT 0);
CREATE TABLE notifyd_routes ( id TEXT PRIMARY KEY, name TEXT NOT NULL DEFAULT '', enabled INTEGER NOT NULL DEFAULT 1, channel_id TEXT NOT NULL DEFAULT 'local', min_severity TEXT NOT NULL DEFAULT 'warning', category TEXT NOT NULL DEFAULT '', event TEXT NOT NULL DEFAULT '', source TEXT NOT NULL DEFAULT '', options_json TEXT NOT NULL DEFAULT '{}', created_at INTEGER NOT NULL DEFAULT 0, updated_at INTEGER NOT NULL DEFAULT 0);
CREATE TABLE notifyd_settings ( id INTEGER PRIMARY KEY CHECK(id=1), enabled INTEGER NOT NULL DEFAULT 1, default_channel_id TEXT NOT NULL DEFAULT 'local', max_attempts INTEGER NOT NULL DEFAULT 3, retry_base_s INTEGER NOT NULL DEFAULT 60, retry_max_s INTEGER NOT NULL DEFAULT 3600, updated_at INTEGER NOT NULL DEFAULT 0, smtp_host TEXT NOT NULL DEFAULT '', smtp_port INTEGER NOT NULL DEFAULT 465, smtp_security TEXT NOT NULL DEFAULT 'ssl', smtp_from TEXT NOT NULL DEFAULT '', smtp_username TEXT NOT NULL DEFAULT '', smtp_password TEXT NOT NULL DEFAULT '');
CREATE TABLE ota_jobs ( id TEXT PRIMARY KEY, package_id TEXT NOT NULL DEFAULT '', package_type TEXT NOT NULL DEFAULT '', from_version TEXT NOT NULL DEFAULT '', to_version TEXT NOT NULL DEFAULT '', state TEXT NOT NULL DEFAULT 'idle', progress INTEGER NOT NULL DEFAULT 0, manifest_json TEXT NOT NULL DEFAULT '{}', error TEXT NOT NULL DEFAULT '', created_at INTEGER NOT NULL DEFAULT 0, updated_at INTEGER NOT NULL DEFAULT 0);
CREATE TABLE ota_slots ( slot_name TEXT PRIMARY KEY, version TEXT NOT NULL DEFAULT '', build_id TEXT NOT NULL DEFAULT '', state TEXT NOT NULL DEFAULT 'unknown', boot_attempts INTEGER NOT NULL DEFAULT 0, last_boot_at INTEGER NOT NULL DEFAULT 0, last_good_at INTEGER NOT NULL DEFAULT 0, last_error TEXT NOT NULL DEFAULT '', rootfs_sha256 TEXT NOT NULL DEFAULT '', updated_at INTEGER NOT NULL DEFAULT 0);
CREATE TABLE ota_state ( key TEXT PRIMARY KEY, value TEXT NOT NULL DEFAULT '', updated_at INTEGER NOT NULL DEFAULT 0);
CREATE TABLE physical_port ( name TEXT PRIMARY KEY, label TEXT DEFAULT '', kind TEXT DEFAULT 'ethernet', speed_label TEXT DEFAULT '', duplex TEXT DEFAULT '', owner_type TEXT DEFAULT '', owner_id TEXT DEFAULT '', status TEXT DEFAULT '', updated_at INTEGER DEFAULT 0);
CREATE TABLE physical_port_config ( ifname TEXT PRIMARY KEY, configured_speed_mbps INTEGER DEFAULT 0, configured_duplex TEXT DEFAULT '', configured_autoneg INTEGER DEFAULT -1, profile_id TEXT DEFAULT '', native_vlan INTEGER DEFAULT 0, tagged_vlans_json TEXT DEFAULT '[]', poe_enabled INTEGER DEFAULT -1, poe_mode TEXT DEFAULT '', display_name TEXT DEFAULT '', sort_order INTEGER DEFAULT 0, updated_at INTEGER DEFAULT 0, last_apply_at INTEGER DEFAULT 0, last_apply_ok INTEGER DEFAULT 0, last_apply_error TEXT DEFAULT '');
CREATE TABLE physical_port_profile ( id TEXT PRIMARY KEY, name TEXT NOT NULL DEFAULT '', native_vlan INTEGER DEFAULT 0, tagged_vlans_json TEXT DEFAULT '[]', poe_enabled INTEGER DEFAULT -1, poe_mode TEXT DEFAULT '', stp_guard TEXT DEFAULT '', storm_control TEXT DEFAULT '', description TEXT DEFAULT '', updated_at INTEGER DEFAULT 0, created_at INTEGER DEFAULT 0);
CREATE TABLE policy_route_rule(id TEXT PRIMARY KEY,enabled INTEGER NOT NULL DEFAULT 1,priority INTEGER NOT NULL,name TEXT NOT NULL,source_object TEXT NOT NULL DEFAULT '',dest_object TEXT NOT NULL DEFAULT '',proto TEXT NOT NULL DEFAULT 'all',ports TEXT NOT NULL DEFAULT 'any',action TEXT NOT NULL DEFAULT 'route_table',target TEXT NOT NULL DEFAULT '',route_table TEXT NOT NULL DEFAULT '',schedule TEXT NOT NULL DEFAULT 'always',sticky INTEGER NOT NULL DEFAULT 1,comment TEXT NOT NULL DEFAULT '',hit_count INTEGER NOT NULL DEFAULT 0,last_hit INTEGER NOT NULL DEFAULT 0,updated_at INTEGER NOT NULL DEFAULT 0);
CREATE TABLE radius_server ( id TEXT PRIMARY KEY, name TEXT NOT NULL, auth_addr TEXT DEFAULT '', auth_port INTEGER DEFAULT 1812, accounting_addr TEXT DEFAULT '', accounting_port INTEGER DEFAULT 1813, secret_ref TEXT DEFAULT '', enabled INTEGER DEFAULT 1);
CREATE TABLE route_object(id TEXT PRIMARY KEY,enabled INTEGER NOT NULL DEFAULT 1,name TEXT NOT NULL UNIQUE,object_type TEXT NOT NULL,family TEXT NOT NULL DEFAULT 'mixed',value TEXT NOT NULL DEFAULT '',comment TEXT NOT NULL DEFAULT '',updated_at INTEGER NOT NULL DEFAULT 0);
CREATE TABLE route_object_member(id INTEGER PRIMARY KEY AUTOINCREMENT,object_id TEXT NOT NULL,value TEXT NOT NULL,label TEXT NOT NULL DEFAULT '',sort_order INTEGER NOT NULL DEFAULT 0);
CREATE TABLE route_table(id TEXT PRIMARY KEY,name TEXT NOT NULL,table_id INTEGER NOT NULL UNIQUE,role TEXT NOT NULL DEFAULT '',gateway TEXT NOT NULL DEFAULT '',metric INTEGER NOT NULL DEFAULT 0,enabled INTEGER NOT NULL DEFAULT 1,updated_at INTEGER NOT NULL DEFAULT 0);
CREATE TABLE static_route(id TEXT PRIMARY KEY,enabled INTEGER NOT NULL DEFAULT 1,name TEXT NOT NULL,family TEXT NOT NULL DEFAULT 'ipv4',destination TEXT NOT NULL,gateway TEXT NOT NULL DEFAULT '',interface TEXT NOT NULL DEFAULT '',route_table TEXT NOT NULL DEFAULT 'main',metric INTEGER NOT NULL DEFAULT 0,mtu INTEGER NOT NULL DEFAULT 1500,route_type TEXT NOT NULL DEFAULT 'unicast',comment TEXT NOT NULL DEFAULT '',updated_at INTEGER NOT NULL DEFAULT 0);
CREATE TABLE terminal_group ( id TEXT PRIMARY KEY, name TEXT NOT NULL COLLATE NOCASE UNIQUE, description TEXT NOT NULL DEFAULT '', color TEXT NOT NULL DEFAULT '', created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE terminal_group_member ( group_id TEXT NOT NULL, member_key TEXT NOT NULL, mac TEXT NOT NULL DEFAULT '', ip TEXT NOT NULL DEFAULT '', display_name TEXT NOT NULL DEFAULT '', position INTEGER NOT NULL DEFAULT 0, added_at INTEGER NOT NULL, PRIMARY KEY(group_id,member_key), FOREIGN KEY(group_id) REFERENCES terminal_group(id) ON DELETE CASCADE, CHECK(mac<>'' OR ip<>''));
CREATE TABLE upnp_acl ( id TEXT PRIMARY KEY, action TEXT NOT NULL DEFAULT 'allow', external_ports TEXT NOT NULL DEFAULT '1024-65535', internal_cidr TEXT NOT NULL DEFAULT '0.0.0.0/0', internal_ports TEXT NOT NULL DEFAULT '1-65535', remark TEXT DEFAULT '', enabled INTEGER DEFAULT 1, sort_order INTEGER DEFAULT 0);
CREATE TABLE upnp_internal_iface ( service_id INTEGER NOT NULL DEFAULT 1, lan_id TEXT NOT NULL, PRIMARY KEY(service_id, lan_id));
CREATE TABLE upnp_mapping_cache ( id TEXT PRIMARY KEY, protocol TEXT NOT NULL, external_port INTEGER NOT NULL, internal_ip TEXT NOT NULL, internal_port INTEGER NOT NULL, client TEXT DEFAULT '', description TEXT DEFAULT '', lease_seconds INTEGER DEFAULT 0, packets INTEGER DEFAULT 0, updated_at INTEGER DEFAULT 0);
CREATE TABLE upnp_service ( id INTEGER PRIMARY KEY CHECK (id = 1), enabled INTEGER DEFAULT 0, natpmp_enabled INTEGER DEFAULT 1, secure_mode INTEGER DEFAULT 1, external_iface TEXT DEFAULT '', presentation_url TEXT DEFAULT '', download_mbps INTEGER DEFAULT 0, upload_mbps INTEGER DEFAULT 0, lease_file TEXT DEFAULT '/var/run/miniupnpd.leases', uuid TEXT DEFAULT '', model_name TEXT DEFAULT 'DreamingWrt Gateway', port_start INTEGER DEFAULT 1024, port_end INTEGER DEFAULT 65535, notify_interval INTEGER DEFAULT 30, clean_interval INTEGER DEFAULT 600, log_packets INTEGER DEFAULT 0, system_uptime INTEGER DEFAULT 1, force_forwarding INTEGER DEFAULT 0, use_stun INTEGER DEFAULT 0, stun_host TEXT DEFAULT '', stun_port INTEGER DEFAULT 3478, pcp INTEGER DEFAULT 1, updated_at INTEGER DEFAULT 0);
CREATE TABLE wan ( id TEXT PRIMARY KEY, name TEXT NOT NULL, note TEXT DEFAULT '', carrier TEXT DEFAULT '', ifname TEXT NOT NULL, device TEXT NOT NULL, port_label TEXT DEFAULT '', access_mode TEXT NOT NULL DEFAULT 'dhcp', gateway TEXT DEFAULT '', dns_json TEXT DEFAULT '[]', ipv6_mode TEXT DEFAULT 'disabled', ipv6_addr TEXT DEFAULT '', delegated_prefix TEXT DEFAULT '', vlan_enabled INTEGER DEFAULT 0, vlan_id TEXT DEFAULT '', mtu INTEGER DEFAULT 1500, metric INTEGER DEFAULT 10, role TEXT DEFAULT 'primary', expected_down_mbps INTEGER DEFAULT 0, expected_up_mbps INTEGER DEFAULT 0, smart_queue INTEGER DEFAULT 0, upnp INTEGER DEFAULT 0, ddns INTEGER DEFAULT 0, enabled INTEGER DEFAULT 1, username TEXT DEFAULT '', password_ref TEXT DEFAULT '', pppoe_multi_json TEXT DEFAULT '{}', created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE wan_address ( id TEXT PRIMARY KEY, wan_id TEXT NOT NULL, ip TEXT NOT NULL, prefix INTEGER NOT NULL, is_primary INTEGER DEFAULT 0, sort_order INTEGER NOT NULL, UNIQUE(wan_id, ip, prefix));
CREATE TABLE wan_advanced ( wan_id TEXT PRIMARY KEY, default_route INTEGER DEFAULT 0, failover INTEGER DEFAULT 1, link_time TEXT DEFAULT '00:00-23:59', health_enabled INTEGER DEFAULT 1, health_mode TEXT DEFAULT 'ping', health_targets_json TEXT DEFAULT '[]', dhcp_hostname TEXT DEFAULT '', dhcp_vendor_class TEXT DEFAULT '', dhcp_client_id TEXT DEFAULT '', pppoe_timing_restart INTEGER DEFAULT 0, pppoe_restart_week TEXT DEFAULT '1234567', pppoe_restart_time TEXT DEFAULT '04:00', pppoe_abnormal_ip_check INTEGER DEFAULT 0, pppoe_abnormal_ip_prefixes TEXT DEFAULT '10,172,192.168', pppoe_ac TEXT DEFAULT '', pppoe_ac_mac TEXT DEFAULT '', pppoe_service TEXT DEFAULT '');
CREATE TABLE wan_bond ( wan_id TEXT PRIMARY KEY, enabled INTEGER DEFAULT 0, bond_name TEXT DEFAULT '', mode TEXT DEFAULT '802.3ad', hash_policy TEXT DEFAULT 'layer3+4', members_json TEXT DEFAULT '[]');
CREATE TABLE wan_dns_policy ( id INTEGER PRIMARY KEY AUTOINCREMENT, wan_id TEXT NOT NULL, upstream_id TEXT DEFAULT '', mode TEXT NOT NULL DEFAULT 'auto', dns_servers TEXT DEFAULT '[]', domains TEXT DEFAULT '[]', sort_order INTEGER DEFAULT 0, enabled INTEGER DEFAULT 1, updated_at INTEGER NOT NULL, FOREIGN KEY(wan_id) REFERENCES wan(id) ON DELETE CASCADE);
CREATE TABLE web_auth_failures ( scope TEXT NOT NULL, auth_key TEXT NOT NULL, fail_count INTEGER NOT NULL DEFAULT 0, first_failed_at INTEGER NOT NULL DEFAULT 0, last_failed_at INTEGER NOT NULL DEFAULT 0, locked_until INTEGER NOT NULL DEFAULT 0, banned INTEGER NOT NULL DEFAULT 0, ban_reason TEXT NOT NULL DEFAULT '', updated_at INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(scope,auth_key));
CREATE TABLE web_auth_settings ( id INTEGER PRIMARY KEY CHECK (id = 1), brute_enabled INTEGER NOT NULL DEFAULT 1, fail_window_s INTEGER NOT NULL DEFAULT 300, max_failures INTEGER NOT NULL DEFAULT 5, lock_s INTEGER NOT NULL DEFAULT 1800, ip_ban_enabled INTEGER NOT NULL DEFAULT 1, ip_fail_window_s INTEGER NOT NULL DEFAULT 600, ip_max_failures INTEGER NOT NULL DEFAULT 20, ip_ban_s INTEGER NOT NULL DEFAULT 0, twofa_issuer TEXT NOT NULL DEFAULT 'DreamingWrt', twofa_step_s INTEGER NOT NULL DEFAULT 30, twofa_digits INTEGER NOT NULL DEFAULT 6, twofa_window INTEGER NOT NULL DEFAULT 1, updated_at INTEGER NOT NULL DEFAULT 0);
CREATE TABLE web_user_group_members ( group_id TEXT NOT NULL, username TEXT NOT NULL, created_at INTEGER NOT NULL, PRIMARY KEY(group_id,username), FOREIGN KEY(group_id) REFERENCES web_user_groups(id) ON DELETE CASCADE, FOREIGN KEY(username) REFERENCES web_users(username) ON DELETE CASCADE);
CREATE TABLE web_user_groups ( id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE, description TEXT NOT NULL DEFAULT '', created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE web_users ( username TEXT PRIMARY KEY, password_hash TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'enabled', role TEXT NOT NULL DEFAULT 'admin', permissions_json TEXT NOT NULL DEFAULT '[]', twofa_enabled INTEGER NOT NULL DEFAULT 0, twofa_secret TEXT NOT NULL DEFAULT '', twofa_bound_at INTEGER NOT NULL DEFAULT 0, twofa_last_counter INTEGER NOT NULL DEFAULT -1, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, last_login_at INTEGER NOT NULL DEFAULT 0, twofa_step_s INTEGER NOT NULL DEFAULT 30, twofa_digits INTEGER NOT NULL DEFAULT 6, twofa_window INTEGER NOT NULL DEFAULT 1, display_name TEXT NOT NULL DEFAULT '', email TEXT NOT NULL DEFAULT '', assignments_json TEXT NOT NULL DEFAULT '[]');
CREATE TABLE wifi_capabilities (id INTEGER PRIMARY KEY CHECK (id = 1),disabled_func TEXT NOT NULL DEFAULT '',bands TEXT NOT NULL DEFAULT '',max_width INTEGER NOT NULL DEFAULT 160,max_ssids_per_radio INTEGER NOT NULL DEFAULT 8,max_business_ssids_per_radio INTEGER NOT NULL DEFAULT 8,max_ssids_total INTEGER NOT NULL DEFAULT 0,ssid_limit_source TEXT NOT NULL DEFAULT '',updated_at INTEGER NOT NULL DEFAULT 0);
CREATE TABLE wifi_global (id INTEGER PRIMARY KEY CHECK (id = 1),enabled INTEGER NOT NULL DEFAULT 1,country TEXT NOT NULL DEFAULT 'CN',speed_profile TEXT NOT NULL DEFAULT 'conservative',mesh INTEGER NOT NULL DEFAULT 0,auto_link INTEGER NOT NULL DEFAULT 1,band_steering INTEGER NOT NULL DEFAULT 1,fast_roaming INTEGER NOT NULL DEFAULT 1,mlo INTEGER NOT NULL DEFAULT 0,dfs_enabled INTEGER NOT NULL DEFAULT 1,roam_assist INTEGER NOT NULL DEFAULT 0,roam_threshold INTEGER NOT NULL DEFAULT -75,multicast_enhance INTEGER NOT NULL DEFAULT 1,airtime_fairness INTEGER NOT NULL DEFAULT 1,isolated_guest INTEGER NOT NULL DEFAULT 0,updated_at INTEGER NOT NULL DEFAULT 0);
CREATE TABLE wifi_radios (id TEXT PRIMARY KEY,band TEXT NOT NULL,device TEXT NOT NULL,phy TEXT NOT NULL DEFAULT '',hwmode TEXT NOT NULL DEFAULT '',channel INTEGER NOT NULL DEFAULT 0,width INTEGER NOT NULL DEFAULT 20,htmode TEXT NOT NULL DEFAULT '',txpower INTEGER NOT NULL DEFAULT 0,supported_widths TEXT NOT NULL DEFAULT '',country TEXT NOT NULL DEFAULT '',enabled INTEGER NOT NULL DEFAULT 1,excluded_channels TEXT NOT NULL DEFAULT '',bssid TEXT NOT NULL DEFAULT '',driver TEXT NOT NULL DEFAULT '',virtual_interfaces INTEGER NOT NULL DEFAULT 0,max_vaps INTEGER NOT NULL DEFAULT 8,reserved_vaps INTEGER NOT NULL DEFAULT 1,updated_at INTEGER NOT NULL DEFAULT 0);
CREATE TABLE wifi_speed_limits (id TEXT PRIMARY KEY,name TEXT NOT NULL,download_mbps INTEGER NOT NULL DEFAULT 0,upload_mbps INTEGER NOT NULL DEFAULT 0,updated_at INTEGER NOT NULL DEFAULT 0);
CREATE TABLE wifi_ssids (id TEXT PRIMARY KEY,name TEXT NOT NULL,network TEXT NOT NULL DEFAULT 'lan',security TEXT NOT NULL DEFAULT 'WPA3 Personal',encryption TEXT NOT NULL DEFAULT 'sae+ccmp',protocol TEXT NOT NULL DEFAULT 'auto',bands TEXT NOT NULL DEFAULT '2g,5g',enabled INTEGER NOT NULL DEFAULT 1,mlo INTEGER NOT NULL DEFAULT 0,fast_roaming INTEGER NOT NULL DEFAULT 1,ieee80211r INTEGER NOT NULL DEFAULT 0,ieee80211k INTEGER NOT NULL DEFAULT 0,ieee80211v INTEGER NOT NULL DEFAULT 0,rrm INTEGER NOT NULL DEFAULT 0,qbssload INTEGER NOT NULL DEFAULT 0,mobility_domain TEXT NOT NULL DEFAULT '',nasid TEXT NOT NULL DEFAULT '',ft_over_ds INTEGER NOT NULL DEFAULT 1,ft_psk_generate_local INTEGER NOT NULL DEFAULT 1,reassociation_deadline INTEGER NOT NULL DEFAULT 1000,key_rotation INTEGER NOT NULL DEFAULT 0,hidden INTEGER NOT NULL DEFAULT 0,isolate INTEGER NOT NULL DEFAULT 0,pmf TEXT NOT NULL DEFAULT 'optional',vlan TEXT NOT NULL DEFAULT '',remark TEXT NOT NULL DEFAULT '',updated_at INTEGER NOT NULL DEFAULT 0);
